catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || !newValue) {
        g_form.setValue('preview', '');
        return;
    }

    var ga = new GlideAjax('x_konl_visual_card.RecognitionCardUtils');
    ga.addParam('sysparm_name', 'getCardDetails');
    ga.addParam('sysparm_model_sys_id', newValue);
    ga.getXMLAnswer(function (answer) {
        var card = JSON.parse(answer);

        if (!card.success) {
            g_form.setValue('preview', '<p style="color:#999;">Card not found.</p>');
            return;
        }

        var html = '<div style="display:flex; gap:16px; align-items:flex-start; padding:12px; border:1px solid #e0e0e0; border-radius:8px; background:#fafafa;">';

        // Image
        if (card.image_url) {
            html += '<div style="flex-shrink:0;">';
            html += '<img src="' + card.image_url + '" alt="' + card.name + '" style="width:100px; height:auto; border-radius:6px; box-shadow:0 2px 6px rgba(0,0,0,0.1);" />';
            html += '</div>';
        }

        // Details
        html += '<div style="flex:1; min-width:0;">';
        html += '<div style="font-size:16px; font-weight:600; color:#333; margin-bottom:4px;">' + card.name + '</div>';

        if (card.description) {
            html += '<div style="font-size:13px; color:#666; margin-bottom:6px;">' + card.description + '</div>';
        }

        if (card.comments) {
            html += '<div style="font-size:12px; color:#888; font-style:italic; border-top:1px solid #eee; padding-top:6px; margin-top:6px;">' + card.comments + '</div>';
        }

        html += '</div></div>';

        g_form.setValue('preview', html);
    });
}
